package com.autoops.execution.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="executions")public class Execution{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String type;@Column(name="workflow_id")private Long workflowId;@Column(name="command_definition_id")private Long commandDefinitionId;@Column(name="started_by",nullable=false)private Long startedBy;@Column(nullable=false)private String mode="MANUAL";@Column(nullable=false)private Integer concurrency=1;@Column(name="failure_policy",nullable=false)private String failurePolicy="STOP_NEW_MACHINES";@Column(nullable=false)private String status="PENDING";@Column(name="started_at")private Instant startedAt;@Column(name="finished_at")private Instant finishedAt;public Long getId(){return id;}public void setType(String v){type=v;}public void setCommandDefinitionId(Long v){commandDefinitionId=v;}public void setWorkflowId(Long v){workflowId=v;}public void setStartedBy(Long v){startedBy=v;}public void setMode(String v){mode=v;}public void setConcurrency(Integer v){concurrency=v;}public void setFailurePolicy(String v){failurePolicy=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public void setStartedAt(Instant v){startedAt=v;}public void setFinishedAt(Instant v){finishedAt=v;}}
